import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'ornamental-divider';

  // Load GLB mesh
  const glbScene = ctx.glbLoader.get(config.meshUrl);
  const mesh = glbScene.clone(true);
  // Assume the GLB is a single model; add as child
  group.add(mesh);

  // Apply transform
  if (config.position) {
    group.position.set(config.position[0], config.position[1], config.position[2]);
  }
  if (config.rotation) {
    group.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  }
  if (config.scale) {
    group.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  }

  // Store original position for hover animation
  const originalY = group.position.y;

  // GSAP timer references for cleanup
  const tweens = [];

  // --- Interaction handlers (pointer events on the group) ---
  const handlers = {
    pointerover: () => {
      // Rise-in subtle (0.15 scene units up)
      const tween = gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      tweens.push(tween);
    },
    pointerout: () => {
      const tween = gsap.to(group.position, {
        y: originalY,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto'
      });
      tweens.push(tween);
    },
    pointerdown: () => {
      // Press-down effect
      const tween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto'
      });
      tweens.push(tween);
    },
    pointerup: () => {
      // Return with weighted-settle (overshoot)
      const tween = gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto'
      });
      tweens.push(tween);
    },
    click: () => {
      // Emit navigation event
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-home.select');
      }
      // Also trigger press-up if not already (safety)
      handlers.pointerup();
    }
  };

  group.userData.handlers = handlers;

  // Data bindings from config (e.g., trpc.visits.book.slot -> confirmPanel)
  group.userData.dataBindings = config.dataBindings || [];

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill all GSAP animations for this group
    tweens.forEach(tween => tween.kill());
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    // Dispose GLB resources
    mesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
    // Remove from parent if any
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
